// Calendrier des compétitions (mis à jour manuellement)
// Ajouter de nouvelles compétitions ici quand elles sont détectées

const competitions = [
  {
    name: 'Orange POESAM',
    url: 'https://poesam.orange.com',
    deadline_estimated: '2027-05-10',
    opening_estimated: '2027-03-01',
    prize: '100 000 USD',
    status: 'PREPARER',
    priority: 1,
    notes: 'Cible prioritaire Attractor Assists. Jury local CI = levier.'
  },
  {
    name: 'AfricaTech Award (VivaTech)',
    url: 'https://challenges.vivatech.com',
    deadline_estimated: '2027-02-15',
    opening_estimated: '2027-01-10',
    prize: 'Visibilité Paris + réseau IFC',
    status: 'PREPARER',
    priority: 1,
    notes: 'Condition bloquante : 150k USD levés. Cible 2028 réaliste.'
  },
  {
    name: 'Africa Business Heroes',
    url: 'https://africabusinessheroes.org',
    deadline_estimated: '2027-04-28',
    opening_estimated: '2027-03-01',
    prize: '300 000 USD (1er)',
    status: 'PREPARER',
    priority: 1,
    notes: 'Condition bloquante : 3 ans de revenus. Eligible après 02/2027.'
  },
  {
    name: 'Seedstars Africa',
    url: 'https://www.seedstarsworld.com',
    deadline_estimated: 'CONTINU',
    opening_estimated: 'CONTINU',
    prize: '500 000 USD',
    status: 'POSTULER_H2_2026',
    priority: 1,
    notes: 'Seul programme ouvert en continu. Identifier cycle local CI/Nigeria.'
  },
  {
    name: 'UNICEF Venture Fund',
    url: 'https://www.unicefventurefund.org',
    deadline_estimated: '2027-05-17',
    opening_estimated: '2027-03-01',
    prize: '100 000 USD',
    status: 'PREPARER',
    priority: 2,
    notes: 'Angle FemTech ou Climate+Santé. Open source obligatoire.'
  }
];

// Calculer les alertes
const today = new Date();
const alerts = [];

for (const comp of competitions) {
  if (comp.deadline_estimated === 'CONTINU') {
    if (comp.status === 'POSTULER_H2_2026') {
      alerts.push({
        ...comp,
        alert_type: 'ACTION_REQUISE',
        message: `[${comp.name}] PROGRAMME OUVERT EN CONTINU — Identifier le prochain cycle local CI/Nigeria cette semaine.`
      });
    }
    continue;
  }

  const deadline = new Date(comp.deadline_estimated);
  const opening = new Date(comp.opening_estimated);
  const daysToDeadline = Math.ceil((deadline - today) / (1000 * 60 * 60 * 24));
  const daysToOpening = Math.ceil((opening - today) / (1000 * 60 * 60 * 24));

  if (daysToDeadline <= 30 && daysToDeadline > 0) {
    alerts.push({
      ...comp,
      days_remaining: daysToDeadline,
      alert_type: 'DEADLINE_PROCHE',
      message: `🚨 [${comp.name}] DEADLINE DANS ${daysToDeadline} JOURS ! Finaliser et soumettre la candidature.`
    });
  } else if (daysToOpening <= 30 && daysToOpening > 0) {
    alerts.push({
      ...comp,
      days_remaining: daysToOpening,
      alert_type: 'OUVERTURE_PROCHE',
      message: `📅 [${comp.name}] Ouverture des candidatures dans ${daysToOpening} jours. Préparer le dossier.`
    });
  } else if (daysToOpening <= 60 && daysToOpening > 30) {
    alerts.push({
      ...comp,
      days_remaining: daysToOpening,
      alert_type: 'PREPARER',
      message: `📋 [${comp.name}] Ouverture dans ${daysToOpening} jours. Vérifier que le dossier est prêt.`
    });
  }
}

// Résumé hebdomadaire (toujours envoyé)
const summary = {
  type: 'RAPPORT_HEBDO',
  date: today.toISOString().split('T')[0],
  competitions_suivies: competitions.length,
  alerts_actives: alerts.length,
  competitions: competitions.map(c => ({
    name: c.name,
    status: c.status,
    deadline: c.deadline_estimated,
    priority: c.priority
  }))
};

alerts.push(summary);

return alerts.map(a => ({ json: a }));

// Construire le message email de résumé hebdomadaire
const allItems = $input.all();
const alerts = allItems.filter(i => i.json.alert_type !== 'RAPPORT_HEBDO');
const summary = allItems.find(i => i.json.alert_type === 'RAPPORT_HEBDO');

const alertLines = alerts.length > 0
  ? alerts.map(a => `• ${a.json.message}`).join('\n')
  : '• Aucune alerte urgente cette semaine.';

const competitionLines = summary?.json?.competitions
  ? summary.json.competitions.map(c => `  [${c.status}] ${c.name} — deadline : ${c.deadline}`).join('\n')
  : '';

const emailBody = `
RAPPORT HEBDO — VEILLE COMPÉTITIONS AFRICAINES
${summary?.json?.date || new Date().toISOString().split('T')[0]}

━━━ ALERTES ACTIVES ━━━
${alertLines}

━━━ SUIVI COMPLET ━━━
${competitionLines}

━━━ DOSSIERS ━━━
Executive Summary : livrables/commercial/candidatures/attractor-assists/executive-summary.html
One Pager : livrables/commercial/candidatures/attractor-assists/one-pager.html

━━━ NOTION ━━━
Radar Financement : https://app.notion.com/p/3824257524c68131ba72eb3400a989a1

—
Assists — Pilotage Agence Mr Attractor
`;

return [{ json: { subject: `[Veille Compétitions] ${alerts.length} alerte(s) — ${new Date().toISOString().split('T')[0]}`, body: emailBody } }];

// Sauvegarder le rapport dans Supabase pour historique
// Utiliser la table veille_rapports existante
const item = $input.first().json;
return [{
  json: {
    source: 'competitions',
    contenu: JSON.stringify(item),
    created_at: new Date().toISOString()
  }
}];
